def add_noise(source):
    for line in NOISE.splitlines():
        date, kind, author, title, opening, *replies = line.split('|')
        if kind == 'slack':
            text = f'10:12 {author}: {opening}\n\nThread replies (5):\n'
            text += '\n'.join(f'10:{15 + i * 3:02} {reply}' for i, reply in enumerate(replies))
            text += f'\n10:26 {author}: thanks all\n10:29 {replies[0].split(":", 1)[0]}: +1'
        else:
            text = opening + '\n' + '\n'.join(replies)
        source(kind, title, date, author, text)
